using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Mail.Domain;
public sealed class MailMigrationJob:ITenantEntity{private MailMigrationJob(){} public MailMigrationJob(Guid municipalityId,string sourceType,string sourceReference,string targetAddress){Id=Guid.NewGuid();MunicipalityId=municipalityId;SourceType=sourceType.Trim().ToUpperInvariant();SourceReference=sourceReference.Trim();TargetAddress=targetAddress.Trim().ToLowerInvariant();State="CREATED";CreatedAt=UpdatedAt=DateTimeOffset.UtcNow;}public Guid Id{get;private set;}public Guid MunicipalityId{get;private set;}public string SourceType{get;private set;}=string.Empty;public string SourceReference{get;private set;}=string.Empty;public string TargetAddress{get;private set;}=string.Empty;public string State{get;private set;}=string.Empty;public int ImportedMessages{get;private set;}public int FailedMessages{get;private set;}public string? LastError{get;private set;}public DateTimeOffset CreatedAt{get;private set;}public DateTimeOffset UpdatedAt{get;private set;}public void UpdateProgress(string state,int imported,int failed,string? error){State=state;ImportedMessages=imported;FailedMessages=failed;LastError=error;UpdatedAt=DateTimeOffset.UtcNow;}}
